from behave import given, when, then
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

file_path = "index.html"

@given('the webpage is loaded')
def step_given_webpage_loaded(context):
    context.driver = webdriver.Chrome()
    context.driver.get(f"file://index.html")
    time.sleep(1)

@given('the user sees the seat with data-testid "seat-1-1" is available')
def step_given_seat_available(context):
    seat = WebDriverWait(context.driver, 10).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, "[data-testid='seat-1-1']"))
    )
    assert not seat.get_attribute("class").contains("occupied"), "Seat is occupied"
    time.sleep(1)

@when('the user clicks on the seat with data-testid "seat-1-1"')
def step_when_user_clicks_seat(context):
    seat = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='seat-1-1']"))
    )
    seat.click()
    time.sleep(1)

@when('the user selects "Fargo ($12)" from the dropdown with data-testid "movie-select"')
def step_when_user_selects_movie(context):
    movie_select = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='movie-select']"))
    )
    movie_select.click()
    option = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='movie-option-2']"))
    )
    option.click()
    time.sleep(1)

@then('the seat with data-testid "seat-1-1" should be marked as selected')
def step_then_seat_marked_selected(context):
    seat = WebDriverWait(context.driver, 10).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, "[data-testid='seat-1-1']"))
    )
    assert "selected" in seat.get_attribute("class"), "Seat is not marked as selected"
    time.sleep(1)

@then('the selected count with data-testid "selected-count" should display "1"')
def step_then_selected_count_display(context):
    selected_count = WebDriverWait(context.driver, 10).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, "[data-testid='selected-count']"))
    )
    assert selected_count.text.strip() == "1", f"Expected selected count to be '1', but got '{selected_count.text.strip()}'"
    time.sleep(1)

@then('the total price with data-testid "total-price" should display "12"')
def step_then_total_price_display(context):
    total_price = WebDriverWait(context.driver, 10).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, "[data-testid='total-price']"))
    )
    assert total_price.text.strip() == "12", f"Expected total price to be '12', but got '{total_price.text.strip()}'"
    time.sleep(1)

def after_scenario(context, scenario):
    context.driver.quit()

