from behave import given, when, then
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

file_path = "index.html"

@given('the movie seat booking page is loaded')
def step_given_page_is_loaded(context):
    context.driver = webdriver.Chrome()
    context.driver.get(f"file://index.html")
    time.sleep(1)

@given('the user selects "The Big Lebowski ($10)" from the movie dropdown with data-testid "movie-select"')
def step_given_select_movie(context):
    movie_select = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='movie-select']"))
    )
    movie_select.click()
    time.sleep(1)
    option = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='movie-option-1']")
    option.click()
    time.sleep(1)

@given('the user sees 0 seats selected and a total price of $0')
def step_given_initial_seat_count_and_price(context):
    selected_count = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='selected-count']")
    total_price = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='total-price']")
    assert selected_count.text.strip() == "0", f"Expected 0 seats selected, but got {selected_count.text.strip()}"
    assert total_price.text.strip() == "0", f"Expected total price $0, but got {total_price.text.strip()}"

@when('the user clicks on an available seat with data-testid "seat-1-1"')
def step_when_click_on_seat(context):
    seat = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='seat-1-1']"))
    )
    seat.click()
    time.sleep(1)

@then('the seat with data-testid "seat-1-1" should be marked as selected')
def step_then_seat_marked_selected(context):
    seat = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='seat-1-1']")
    assert "selected" in seat.get_attribute("class").split(), "Seat is not marked as selected"

@then('the user should see 1 seat selected and a total price of $10')
def step_then_seat_count_and_price_updated(context):
    selected_count = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='selected-count']")
    total_price = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='total-price']")
    assert selected_count.text.strip() == "1", f"Expected 1 seat selected, but got {selected_count.text.strip()}"
    assert total_price.text.strip() == "10", f"Expected total price $10, but got {total_price.text.strip()}"

@then('local storage should contain the index of the selected seat')
def step_then_local_storage_contains_seat_index(context):
    selected_seats = context.driver.execute_script("return localStorage.getItem('selectedSeats');")
    assert selected_seats is not None, "Local storage does not contain selected seats"
    assert "0" in selected_seats, f"Expected seat index 0 in local storage, but got {selected_seats}"

def after_scenario(context, scenario):
    context.driver.quit()

from behave import given, when, then
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

file_path = "index.html"

def is_seat_selected(element):
    return "selected" in element.get_attribute("class").split()

@given('the movie seat booking page is loaded')
def step_given_page_loaded(context):
    context.driver = webdriver.Chrome()
    context.driver.get(f"file://index.html")
    time.sleep(1)

@given('the user selects "O Brother ($8)" from the movie dropdown with data-testid "movie-select"')
def step_given_select_movie(context):
    movie_select = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='movie-select']"))
    )
    movie_select.click()
    time.sleep(1)
    option = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='movie-option-3']")
    option.click()
    time.sleep(1)

@given('the user sees 0 seats selected and a total price of $0')
def step_given_initial_seat_selection(context):
    selected_count = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='selected-count']")
    total_price = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='total-price']")
    assert selected_count.text.strip() == "0", f"Expected 0 seats selected, but got {selected_count.text.strip()}"
    assert total_price.text.strip() == "0", f"Expected total price $0, but got {total_price.text.strip()}"

@when('the user clicks on an occupied seat with data-testid "seat-2-4"')
def step_when_click_occupied_seat(context):
    occupied_seat = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='seat-2-4']")
    occupied_seat.click()
    time.sleep(1)

@then('the seat with data-testid "seat-2-4" should remain occupied and not be marked as selected')
def step_then_seat_remains_occupied(context):
    occupied_seat = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='seat-2-4']")
    assert not is_seat_selected(occupied_seat), "Occupied seat should not be marked as selected"

@then('the user should see 0 seats selected and a total price of $0')
def step_then_verify_seat_selection(context):
    selected_count = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='selected-count']")
    total_price = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='total-price']")
    assert selected_count.text.strip() == "0", f"Expected 0 seats selected, but got {selected_count.text.strip()}"
    assert total_price.text.strip() == "0", f"Expected total price $0, but got {total_price.text.strip()}"

@then('local storage should not contain the index of the occupied seat')
def step_then_verify_local_storage(context):
    # This step requires JavaScript execution to check local storage
    selected_seats = context.driver.execute_script("return localStorage.getItem('selectedSeats');")
    assert selected_seats is not None, "Local storage should have 'selectedSeats' key"
    assert "11" not in selected_seats, "Occupied seat index should not be in local storage"

def after_scenario(context, scenario):
    context.driver.quit()

from behave import given, when, then
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

file_path = "index.html"

@given('the movie seat booking page is loaded')
def step_given_page_loaded(context):
    context.driver = webdriver.Chrome()
    context.driver.get(f"file://index.html")
    time.sleep(1)

@given('the user selects "No Country for Old Men ($9)" from the movie dropdown with data-testid "movie-select"')
def step_given_select_movie(context):
    movie_select = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='movie-select']"))
    )
    movie_select.click()
    time.sleep(1)
    option = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='movie-option-4']")
    option.click()
    time.sleep(1)

@given('the user clicks on an available seat with data-testid "seat-1-1"')
def step_given_click_seat(context):
    seat = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='seat-1-1']"))
    )
    seat.click()
    time.sleep(1)

@given('the user sees 1 seat selected and a total price of $9')
def step_given_verify_selection(context):
    selected_count = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='selected-count']")
    total_price = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='total-price']")
    assert selected_count.text.strip() == "1", f"Expected 1 seat selected, but got {selected_count.text.strip()}"
    assert total_price.text.strip() == "9", f"Expected total price $9, but got {total_price.text.strip()}"

@when('the user clicks again on the seat with data-testid "seat-1-1"')
def step_when_click_again(context):
    seat = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='seat-1-1']"))
    )
    seat.click()
    time.sleep(1)

@then('the seat with data-testid "seat-1-1" should be deselected')
def step_then_verify_deselection(context):
    seat = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='seat-1-1']")
    assert "selected" not in seat.get_attribute("class"), "Seat should be deselected"

@then('the user should see 0 seats selected and a total price of $0')
def step_then_verify_no_selection(context):
    selected_count = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='selected-count']")
    total_price = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='total-price']")
    assert selected_count.text.strip() == "0", f"Expected 0 seats selected, but got {selected_count.text.strip()}"
    assert total_price.text.strip() == "0", f"Expected total price $0, but got {total_price.text.strip()}"

@then('local storage should not contain the index of the deselected seat')
def step_then_verify_local_storage(context):
    seat_index = context.driver.execute_script("return localStorage.getItem('selectedSeats');")
    assert seat_index is None or "0" not in seat_index, "Local storage should not contain the index of the deselected seat"

def after_scenario(context, scenario):
    context.driver.quit()

from behave import given, when, then
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

file_path = "index.html"

def is_selected(element):
    return "selected" in element.get_attribute("class").split()

@given('the webpage "Movie Seat Booking" is loaded')
def step_given_webpage_loaded(context):
    context.driver = webdriver.Chrome()
    context.driver.get(f"file://index.html")
    time.sleep(1)

@given('local storage does not contain "selectedSeats" or "selectedMovieIndex"')
def step_given_local_storage_empty(context):
    context.driver.execute_script("localStorage.removeItem('selectedSeats');")
    context.driver.execute_script("localStorage.removeItem('selectedMovieIndex');")
    time.sleep(1)

@when('the page loads')
def step_when_page_loads(context):
    # This step is implicitly covered by the page load in the background
    pass

@then('no seats should have the class "selected"')
def step_then_no_seats_selected(context):
    seats = context.driver.find_elements(By.CSS_SELECTOR, ".row .seat")
    for seat in seats:
        assert not is_selected(seat), "Expected no seat to be selected"
    time.sleep(1)

@then('the first movie option with data-testid "movie-option-1" should be selected in the dropdown')
def step_then_first_movie_selected(context):
    movie_select = WebDriverWait(context.driver, 10).until(
        EC.presence_of_element_located((By.CSS_SELECTOR, "[data-testid='movie-select']"))
    )
    selected_option = movie_select.find_element(By.CSS_SELECTOR, "[data-testid='movie-option-1']")
    assert selected_option.is_selected(), "Expected the first movie option to be selected"
    time.sleep(1)

def after_scenario(context, scenario):
    context.driver.quit()

