from behave import given, when, then
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

file_path = "index.html"

@given('the movie seat booking page is loaded')
def step_given_movie_seat_booking_page_loaded(context):
    context.driver = webdriver.Chrome()
    context.driver.get(f"file://index.html")
    time.sleep(1)

@given('the user selects "Fargo ($12)" from the movie dropdown with data-testid "movie-select"')
def step_given_user_selects_movie(context):
    movie_select = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='movie-select']"))
    )
    movie_select.click()
    time.sleep(1)
    fargo_option = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='movie-option-2']")
    fargo_option.click()
    time.sleep(1)

@when('the user clicks on the seat with data-testid "seat-2-1"')
def step_when_user_clicks_seat(context):
    seat = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='seat-2-1']"))
    )
    seat.click()
    time.sleep(1)

@when('the user clicks again on the seat with data-testid "seat-2-1"')
def step_when_user_clicks_seat_again(context):
    seat = WebDriverWait(context.driver, 10).until(
        EC.element_to_be_clickable((By.CSS_SELECTOR, "[data-testid='seat-2-1']"))
    )
    seat.click()
    time.sleep(1)

@then('the selected seat count displayed with data-testid "selected-count" should be "0"')
def step_then_selected_seat_count_should_be_zero(context):
    selected_count = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='selected-count']")
    assert selected_count.text.strip() == "0", f"Expected '0', but got '{selected_count.text.strip()}'"

@then('the total price displayed with data-testid "total-price" should be "$0"')
def step_then_total_price_should_be_zero(context):
    total_price = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='total-price']")
    assert total_price.text.strip() == "0", f"Expected '$0', but got '{total_price.text.strip()}'"

def after_scenario(context, scenario):
    context.driver.quit()

