from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
import time

file_path = "index.html"

@given('the Movie Seat Booking page is loaded')
def step_given_page_is_loaded(context):
    context.driver = webdriver.Chrome()
    context.driver.get(f"file://index.html")
    time.sleep(1)  # Allow time for the page to load

@given('the seat with data-testid "seat-2-4" is occupied')
def step_given_seat_is_occupied(context):
    seat = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='seat-2-4']")
    assert "occupied" in seat.get_attribute("class"), "Seat is not occupied"

@when('the user clicks on the seat with data-testid "seat-2-4"')
def step_when_user_clicks_occupied_seat(context):
    seat = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='seat-2-4']")
    seat.click()
    time.sleep(1)  # Allow time for any potential UI updates

@then('the seat with data-testid "seat-2-4" should remain occupied')
def step_then_seat_remains_occupied(context):
    seat = context.driver.find_element(By.CSS_SELECTOR, "[data-testid='seat-2-4']")
    assert "occupied" in seat.get_attribute("class"), "Seat is not occupied"

@then('the selected seat count should remain "0"')
def step_then_selected_seat_count_remains_zero(context):
